def test_ad_ramp_and_nonzero_initial_history(self):
    result = execute_delay()
    for actual, answer in zip(column(result), [-1, -1, 0, 1, 1]):
        self.assertAlmostEqual(actual, answer, delta=2e-14)
    self.assertEqual(result["transient"]["events"], [])
    self.assertTrue(all(row["max_residual_ratio"] <= 1 for row in result["solutions"]))

def test_ad_zero_is_current_input_identity_extension(self):
    times = [0, 2e-9, 4e-9, 10e-9]
    result = execute_delay(instances=[instance(parameters={"tau": 0})], times=times)
    for actual, answer in zip(column(result), [-1, 0, 1, 1]):
        self.assertAlmostEqual(actual, answer, delta=2e-14)

def test_delay_beyond_stop_preserves_initial_value(self):
    result = execute_delay(instances=[instance(parameters={"tau": 100e-9})])
    self.assertEqual(column(result), [-1]*5)

def test_semantic_history_is_independent_of_output_grid_and_maxstep(self):
    points = [[0, -1], [1e-9, 2], [1.125e-9, -2], [2e-9, .5], [10e-9, .5]]
    times = [0, 3.5e-9, 4.0625e-9, 4.5e-9, 7e-9, 10e-9]
    dense = sorted(set(times + [i*.125e-9 for i in range(80)]))
    answers = [expected(points, t, DEFAULT_DELAY) for t in times]
    baseline = None
    for grid in [times, dense]:
        for step in [100e-9, .17e-9]:
            with self.subTest(grid=len(grid), step=step):
                result = execute_delay(sources={"u": points}, times=grid, step=step)
                values = [column(result)[grid.index(t)] for t in times]
                for actual, answer in zip(values, answers):
                    self.assertAlmostEqual(actual, answer, delta=3e-13)
                if baseline is None:
                    baseline = values
                self.assertEqual(values, baseline)

def test_cross_on_delayed_output_direct_or_indirect_is_rejected(self):
    for guard in ["V(y,r)-0.5", "V(z,r)-0.5", "0*V(z,r)+V(u,r)-0.5"]:
        source = model(f'''@(initial_step) n=0;
          V(y,r)<+absdelay(V(u,r),1n); V(z,r)<+2*V(y,r);
          @(cross({guard},1)) n=n+1;''', "integer n; electrical z;")
        with self.subTest(guard=guard), self.assertRaises((CompileError, KernelError)):
            execute_delay(source)

def test_dynamic_delay_maxdelay_and_implicit_delay_rejected(self):
    for expression in ["absdelay(V(u),-1n)", "absdelay(V(u),V(u))",
                       "absdelay(V(u),1n,2n)", "absdelay(V(u))"]:
        with self.subTest(expression=expression), self.assertRaises(CompileError):
            compile_delay(model(f"V(y,r)<+{expression};"))

def test_two_instances_and_per_call_parameters_remain_separate(self):
    points = [[0,0],[2,2],[8,2]]
    times = [0,1,2,3,4,5,8]
    a = instance('a', connections={'u':'u','y':'a','r':'0'},parameters={'d1':1,'d2':2})
    b = instance('b', connections={'u':'u','y':'b','r':'0'},parameters={'d1':0,'d2':1})
    body = 'V(y,r)<+absdelay(absdelay(V(u,r),d1),d2);'
    for order in [[a,b],[b,a]]:
        result = run(body,points,times,instances=order)
        for node,d1,d2 in [('a',1,2),('b',0,1)]:
            self.assertEqual(values(result,node),[float(answer(points,t,d1,d2)) for t in times])

def test_equivalent_equation_scales_and_contribution_forms(self):
    forms = [SCALED, model(
        'V(y,r)<+V(y,r); V(r,y)<+s*(V(y,r)+pow(V(y,r),3)-1);',
        'parameter real s=1;')]
    for source in forms:
        for scale in (1, 1e-13, -1e-13, 1e3):
            with self.subTest(source=source, scale=scale):
                row, _ = run(source, [instance(parameters={'s': scale})])[0]
                self.assertLessEqual(abs(Decimal(row['y']) - ROOT), Decimal('1e-10'))

def test_active_initial_snapshot_of_input_selected_seed_is_rejected(self):
    with self.assertRaises(CompileError):
        compile_body('''@(initial_step) begin q=V(u,r)>0?1:0;
            $strobe("q=%d",q); end V(y,r)<+q;''')

def test_active_initial_voltage_or_history_reads_are_rejected(self):
    for expr in ['V(u,r)','V(y,r)','transition(1,0,0.1,0.1)']:
        with self.subTest(expr=expr), self.assertRaises(CompileError):
            compile_body('@(initial_step) $strobe("v=%g",'+expr+'); V(y,r)<+q;')
    with self.assertRaises(CompileError):
        compile_body('''@(initial_step) begin if(V(u,r)>0) $display("yes"); end V(y,r)<+q;''')

def test_constant_initial_output_with_no_states(self):
    p=compile_body('''@(initial_step) $strobe("fixed=%.2f",1.25);
        V(y,r)<+1;''','')
    self.assertEqual(texts(run(p)),[(0,'fixed=1.25')])

def test_invalid_fixed_formats_and_arity_are_rejected(self):
    for fmt,args in [('%.33f',',1'),('%.03f',',1'),('%.f',',1'),('%.0g',',1'),('%.2d',',1'),('%f','')]:
        with self.subTest(fmt=fmt),self.assertRaises(CompileError):
            compile_body('@(timer(0.5)) $strobe("'+fmt+'"'+args+'); V(y,r)<+q;')

def test_raw_ir_cannot_turn_active_initial_snapshots_into_state_writes_or_voltage_reads(self):
    p=compile_body('@(initial_step) $strobe("seed=%g",1); V(y,r)<+q;').to_dict()
    for mode in ['state_write','voltage_read']:
        payload=copy.deepcopy(p)
        if mode=='state_write':
            payload['events'][0]['body']=(dict(kind='assign',state=0,rhs=dict(op='affine',constant=2,terms=[])), *payload['events'][0]['body'])
        else:
            payload['events'][0]['body'][0]['args']=[dict(op='affine',constant=0,terms=[dict(node=p['nodes'].index('y'),coefficient=1)])]
        with self.subTest(mode=mode),self.assertRaises(KernelError):
            _invoke(dict(program=payload,driven=['u'],samples=[],transient=dict(
                pwl=[[[0,1],[1,1]]],output_times=[0,1],stop=1,max_step=1)),KERNEL)

def test_runtime_strobe_fixed_formats_and_rejected_trials_do_not_duplicate(self):
    p=compile_body('''@(initial_step) q=2;
        @(timer(0.5)) begin $strobe("before=%d",q); q=q+1;
          $strobe("q=%d t=%.3f neg=%.2f zero=%.0f default=%f %%",q,$abstime,-1.25,-0.0001,1.5);
        end V(y,r)<+q;''')
    r=run(p,[0,1])
    self.assertGreater(r['transient']['discarded_trials'],0)
    self.assertEqual(texts(r),[(.5,'before=2'),(.5,'q=3 t=0.500 neg=-1.25 zero=-0 default=1.500000 %')])

def test_separate_initial_blocks_and_static_condition_preserve_source_order(self):
    p=compile_body('''@(initial_step) q=1;
        @(initial_step) begin $display("a=%d",q);
            if (pick>0) begin q=4; $strobe("yes=%d",q); end
            else begin q=8; $strobe("no=%d",q); end end
        @(initial_step) begin q=q+2; $strobe("b=%d",q); end
        V(y,r)<+q;''', 'integer q; parameter integer pick=1;')
    self.assertEqual(texts(run(p)),[(0,'a=1'),(0,'yes=4'),(0,'b=6')])

def test_strobe_initial_snapshots_and_cold_history_use_different_values(self):
    p=compile_body('''@(initial_step) begin
        $strobe("before=%d",q); q=3; $strobe("middle=%d",q);
        q=q+2; $strobe("after=%d",q);
        end V(y,r)<+transition(q,0,0.125,0.125);''')
    r=run(p)
    self.assertEqual(texts(r),[(0,'before=0'),(0,'middle=3'),(0,'after=5')])
    self.assertEqual([s['voltages'][r['nodes'].index('y')] for s in r['solutions']],[5]*4)
    self.assertEqual(r['transient']['states'],[[5]]*4)

def test_branch_orientation_and_single_node_access(self):
    for body in ["V(y,r)<+V(u,r); V(r,y)<+-0.125;", "V(y)<+V(u)+0.125;"]:
        self.assertAlmostEqual(execute(model(body))[0]["y"], .325, places=12)

def test_feedback_does_not_require_fixed_point_contraction(self):
    for gain in (-4, 1.5, .999):
        inst = instance(module="dvs_v7_linear", connections=dict(vin="u", vout="y", vref="r"), parameters=dict(gain=gain))
        rows = execute(FEEDBACK, [inst], ["u", "r"], [[.5, .3]])
        self.assertAlmostEqual(rows[0]["y"], .3 + .2/(1-gain), places=9)

def test_feedback_is_solved_at_first_sample_without_history(self):
    inst = instance(module="dvs_v7_linear", connections=dict(vin="u", vout="y", vref="0"))
    rows = execute(FEEDBACK, [inst], samples=[[.2], [.6], [-.3], [.2]])
    self.assertEqual(rows[0], rows[-1])
    for row, expected in zip(rows, [.4, 1.2, -.6, .4]):
        self.assertAlmostEqual(row["y"], expected, places=12)

def test_numeric_scaling_and_precedence(self):
    source = model("V(y,r)<+-(2+3)*V(u,r)/2+1m; V(y,r)<+2e-3;")
    self.assertAlmostEqual(execute(source)[0]["y"], -.497)

def test_parameter_dependencies_follow_instance_overrides(self):
    source = model("V(y,r)<+derived*V(u,r);", "parameter real base=2; parameter real derived=base+1;")
    self.assertAlmostEqual(execute(source, [instance(parameters=dict(base=4))])[0]["y"], 1)

def test_singular_and_floating_circuits_fail(self):
    for source in [model("V(y,r)<+V(u,r)+V(y,r);"),
                   model("V(y,r)<+V(u,r)+V(floating);", "electrical floating;")]:
        with self.subTest(source=source), self.assertRaises(KernelError) as error:
            execute(source)
        self.assertEqual(error.exception.detail["kind"], "singular_system")

def test_source_default_and_overridden_parameters(self):
    for params, expected in [({}, .575), (dict(g1=-.5, g2=2, bias=-.25), .15)]:
        with self.subTest(params=params):
            rows = execute(SUM, [instance(module="dvs_sum", connections=dict(u="u", v="v", vout="y", vref="0"), parameters=params)],
                           ["u", "v"], [[.4, .3]])
