    baseline = None
    for times, step in [(sparse,3), ([k/8 for k in range(25)],.125)]:
        result, actual = rows(program, {"u": [[0,1],[3,1]]}, times, max_step=step)
        self.assertEqual([e["time"] for e in result["transient"]["events"]], [1,2])
        for t, row in zip(times, actual):
