            self.assertAlmostEqual(row["q"], edge, delta=1e-10)
        current = dict(zip(times,actual))
        if baseline is not None:
            for t in sparse:
                for node in ("y","q"):
                    self.assertAlmostEqual(current[t][node], baseline[t][node], delta=1e-10)
        else:
            baseline = current

