    # before idt reads the assert, so idt never sees a nonzero value.
    body = """
      @(timer(1.0e-6, 1.0e-6)) reset = 1;
      reset = 0;
      V(y,r) <+ idt(1.0e6, 0.0, reset);
    """
    self.assertMatches(body, [])

