            elif mutation=='order':e.reverse()
            elif mutation=='timer_before':e[1]['before']=[0,0]
            elif mutation=='timer_after':e[1]['after']=[.5,2]
            elif mutation=='missing_timer':e.pop()
            elif mutation=='duplicate_timer':e.append(copy.deepcopy(e[1]))
