def test_instance_constants_and_call_sites_keep_independent_histories(self):
    body='V(y,r)<+idtmod(V(u,r),ic,1); V(z,r)<+slew(V(u,r),rate);'
    insts=[instance(name=n,connections=dict(u=n+'u',y=n+'y',z=n+'z',r='0'),
                    parameters=dict(ic=ic,rate=rate))
           for n,ic,rate in [('a',0.125,0.25),('b',0.375,0.5)]]
    for order in [insts,insts[::-1]]:
        p=program(body,'parameter real ic=0.125,rate=1;',ports='u,y,z,r',instances=order)
        r=transient(p,{'au':[[0,1],[2,3]],'bu':[[0,-1],[2,-3]]},[0,0.5,1.5],
                    stop=2,max_step=2,kernel=KERNEL)
        for n,ic,rate,sign in [('a',0.125,0.25,1),('b',0.375,0.5,-1)]:
            for actual,t in zip(values(r,n+'y'),[0,0.5,1.5]):
                self.assertAlmostEqual(actual,(ic+sign*(t+t*t/2))%1,delta=2e-13)
            for actual,t in zip(values(r,n+'z'),[0,0.5,1.5]):
                self.assertAlmostEqual(actual,sign*(1+rate*t),delta=2e-13)
        self.assertEqual(len(p.operators),4)
        self.assertEqual({o.origin.instance for o in p.operators},{'a','b'})

def test_sequential_ex01_clamp_uses_original_input(self):
    source = model("f=0.4+0.5*V(u,r); if(f<0.2) f=0.2; "
                   "else if(f>1.0) f=1.0; V(y,r)<+f;", declarations="real f;")
    program = compile_sources({"test.va": source}, [instance()])
    points = [[0.0, -1.0], [2e-6, 0.0], [4e-6, 2.0],
              [6e-6, 0.0], [8e-6, -1.0]]
    times = sorted({0.0, 8e-6, *[i*2e-10 for i in range(40001)],
                    1.2e-6, 3.2e-6, 4.8e-6, 6.8e-6})
    result = transient(program, {"u": points}, times, stop=8e-6,
                       max_step=2e-10, kernel=KERNEL, vabstol=1e-9, reltol=1e-10)
    def expected(time):
        for (start, a), (end, b) in zip(points, points[1:]):
            if time <= end:
                value = Fraction(a)+(Fraction(b)-Fraction(a))*(Fraction(time)-Fraction(start))/(Fraction(end)-Fraction(start))
                return min(Fraction(1.0), max(Fraction(0.2), Fraction(0.4)+Fraction(0.5)*value))
        self.fail("time outside frozen source")
    for time, solution in zip(times, result["solutions"]):
        actual = Fraction(solution["voltages"][result["nodes"].index("y")])
        self.assertLessEqual(abs(actual-expected(time)), Fraction(1e-9))

