        'q=2000;q=0;end V(y)<+1.0*((q>>0)&0);'), [0, 0, 0])
    pending, reads = [program.contributions[0].rhs], set()
    while pending:
        item = pending.pop()
        if isinstance(item, StateRef):
            reads.add(item.state)
        elif isinstance(item, Binary):
            pending.extend((item.left, item.right))
