      V(z,r)<+transition(a,0,0.75,0.75);
      V(w,r)<+transition(b,0,0.75,0.75); V(y,r)<+V(z,r)+V(w,r);''',
      'real a,b; electrical z,w;')
    p=compile_sources({'end-checkpoints.va':source},[instance()])
